/* setBlock */
INSERT INTO TB_USBLOC (
            USER_NUMB
          , BLOC_NUMB
          , REGI_DATE
) VALUES (  #{userNumb}
          , #{blocNumb}
          , CURRENT_TIMESTAMP(6)
) AS NEW
ON DUPLICATE KEY UPDATE
       USER_NUMB = NEW.USER_NUMB

mapper.delete:
DELETE /* delBlock */
  FROM TB_USBLOC
 WHERE USER_NUMB = #{userNumb}
   AND BLOC_NUMB = #{blocNumb}


DELETE /* delBlockInvitations */
  FROM TB_CLMEMX
 WHERE MEMB_STAT = #{memberInvited}
   AND (   (SEND_NUMB = #{userNumb} AND USER_NUMB = #{blocNumb})
        OR (SEND_NUMB = #{blocNumb} AND USER_NUMB = #{userNumb})
       )
